--liquibase formatted sql

-- Этап 2, заклинания (contract): таблицы больше не нужны, данные — в jsonb (0013).
-- Rollback восстанавливает таблицы из jsonb (id времени сотворения выдаются заново).

--changeset pg-migration:0014-drop-spells_times
DROP TABLE spells_times;
--rollback CREATE TABLE spells_times (id integer generated by default as identity PRIMARY KEY, "condition" varchar(255), number integer NOT NULL, unit varchar(255) COLLATE ci NOT NULL, spell_id integer NOT NULL REFERENCES spells (id));
--rollback INSERT INTO spells_times (spell_id, number, unit, "condition") SELECT s.id, (x.v ->> 'number')::integer, x.v ->> 'unit', x.v ->> 'condition' FROM spells s CROSS JOIN LATERAL jsonb_array_elements(s.times) WITH ORDINALITY AS x(v, n) ORDER BY s.id, x.n;

--changeset pg-migration:0014-drop-spell_damage_type
DROP TABLE spell_damage_type;
--rollback CREATE TABLE spell_damage_type (spell_id integer NOT NULL REFERENCES spells (id), damage_type varchar(255) COLLATE ci NOT NULL, sort_order integer NOT NULL CHECK (sort_order >= 0), PRIMARY KEY (spell_id, sort_order));
--rollback INSERT INTO spell_damage_type (spell_id, damage_type, sort_order) SELECT s.id, x.v, x.n - 1 FROM spells s CROSS JOIN LATERAL jsonb_array_elements_text(s.damage_type) WITH ORDINALITY AS x(v, n);

--changeset pg-migration:0014-drop-spell_heal_type
DROP TABLE spell_heal_type;
--rollback CREATE TABLE spell_heal_type (spell_id integer NOT NULL REFERENCES spells (id), heal_type varchar(255) COLLATE ci NOT NULL, sort_order integer NOT NULL CHECK (sort_order >= 0), PRIMARY KEY (spell_id, sort_order));
--rollback INSERT INTO spell_heal_type (spell_id, heal_type, sort_order) SELECT s.id, x.v, x.n - 1 FROM spells s CROSS JOIN LATERAL jsonb_array_elements_text(s.heal_type) WITH ORDINALITY AS x(v, n);

--changeset pg-migration:0014-drop-spell_savingthrows
DROP TABLE spell_savingthrows;
--rollback CREATE TABLE spell_savingthrows (spell_id integer NOT NULL REFERENCES spells (id), ability varchar(255) COLLATE ci NOT NULL, sort_order integer NOT NULL CHECK (sort_order >= 0), PRIMARY KEY (spell_id, sort_order));
--rollback INSERT INTO spell_savingthrows (spell_id, ability, sort_order) SELECT s.id, x.v, x.n - 1 FROM spells s CROSS JOIN LATERAL jsonb_array_elements_text(s.savingthrows) WITH ORDINALITY AS x(v, n);
